<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import { billingLineAmount, calculateBillingDraft, defaultBillingSettings, normalizeBillingDraft } from '~~/shared/utils/billingDraft'
import type { BillingLine } from '~~/shared/utils/billingDraft'
import { renderBillingInvoice } from '~~/shared/utils/billingInvoicePrint'
import { printBillingInvoice, removeBillingPrintFrame } from '~/utils/printBillingInvoice'

const props=defineProps<{detail:any;busy:boolean;error:string}>()
const emit=defineEmits<{(event:'close'):void;(event:'save',body:any):void;(event:'change-status',body:any):void}>()
const clone=<T,>(value:T):T=>JSON.parse(JSON.stringify(value))
const source=props.detail.source,saved=props.detail.draft?.snapshot
const metadata=ref(clone(saved?.source||source?.batch))
const form=ref({lines:clone<BillingLine[]>(saved?.lines||source?.lines||[]),settings:clone(saved?.settings||source?.settings||defaultBillingSettings()),
  billingDate:saved?.billingDate||new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Manila',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date()),notes:saved?.notes||source?.profile?.notes||''})
const sourceHash=ref(props.detail.draft?.sourceHash||source?.sourceHash||'')
const initialForm=JSON.stringify(form.value)
const dirty=computed(()=>JSON.stringify(form.value)!==initialForm)
const finalized=computed(()=>props.detail.draft?.status==='Finalized')
const confirmation=ref(''),reason=ref(''),printing=ref(false),printError=ref('')
const tab=ref('invoice')
const canFinalize=computed(()=>props.detail.permissions?.canFinalize===true&&!dirty.value&&!stale.value&&!!totals.value)
function confirmStatus(){if(props.busy)return;if(confirmation.value==='finalize'&&!canFinalize.value)return;if(confirmation.value==='reopen'&&reason.value.trim().length<5)return;emit('change-status',{action:confirmation.value,revision:props.detail.draft.revision,sourceHash:sourceHash.value,reason:reason.value.trim()})}
const editable=computed(()=>props.detail.permissions?.canEdit===true)
const stale=computed(()=>!!source&&sourceHash.value!==source.sourceHash)
const warnings=computed(()=>(finalized.value?saved?.warnings:source?.warnings||saved?.warnings)||[])
const calculation=computed(()=>{try{const input=normalizeBillingDraft(form.value.lines,form.value.settings);return {totals:calculateBillingDraft(input.lines,input.settings),error:''}}catch(e:any){return {totals:null,error:e.message}}})
const totals=computed(()=>calculation.value.totals)
const employees=computed(()=>(finalized.value?saved?.employees:source?.employees||saved?.employees)||[])
const statementTitle=ref(saved?.profile?.title||source?.profile?.title||'Billing statement')
const reference=props.detail.draft?`BILL-${String(props.detail.draft.billingId).padStart(4,'0')}`:'UNSAVED PREVIEW'
const money=(value:any)=>new Intl.NumberFormat('en-PH',{style:'currency',currency:'PHP'}).format(Number(value)||0)
const number=(value:any)=>Number(value||0).toFixed(2)
const day=(value:string)=>value?new Date(value+'T00:00:00').toLocaleDateString('en-PH',{month:'short',day:'numeric',year:'numeric'}):''
const timestamp=(value:string)=>{if(!value)return '';const date=new Date(value.replace(' ','T'));return Number.isFinite(date.getTime())?date.toLocaleString('en-PH',{month:'short',day:'numeric',year:'numeric',hour:'numeric',minute:'2-digit',hour12:true}):value}
function addLine(){let index=1;while(form.value.lines.some(line=>line.id===`manual-${index}`))index++;form.value.lines.push({id:`manual-${index}`,description:'',quantity:1,unit:'item',rate:0,direction:'Charge',category:'Additional'})}
function reloadSource(){if(!source)return;form.value.lines=clone(source.lines);sourceHash.value=source.sourceHash;metadata.value=clone(source.batch);statementTitle.value=source.profile.title}
function clientSetup(){if(source)form.value.settings=clone(source.settings)}
function save(){if(!editable.value||!totals.value||stale.value||props.busy)return;emit('save',{...clone(form.value),sourceHash:sourceHash.value,revision:Number(props.detail.draft?.revision||0)})}
async function printDraft(){
  if(printing.value||props.busy||!totals.value)return
  printing.value=true;printError.value=''
  try{await printBillingInvoice(renderBillingInvoice({metadata:metadata.value,lines:form.value.lines,settings:form.value.settings,billingDate:form.value.billingDate,reference,finalized:finalized.value,title:statementTitle.value}))}
  catch(error:any){printError.value=error.message||'Unable to open the print preview. Please try again.'}
  finally{printing.value=false}
}
let previousOverflow=''
const keydown=(event:KeyboardEvent)=>{if(event.key==='Escape'&&!props.busy){if(confirmation.value)confirmation.value='';else emit('close')}}
onMounted(()=>{previousOverflow=document.body.style.overflow;document.body.style.overflow='hidden';window.addEventListener('keydown',keydown)})
onBeforeUnmount(()=>{document.body.style.overflow=previousOverflow;removeBillingPrintFrame();window.removeEventListener('keydown',keydown)})
</script>

<template>
  <Teleport to="body"><div class="billing-draft-backdrop" @click.self="!busy&&emit('close')"><section class="billing-draft-dialog" role="dialog" aria-modal="true" aria-labelledby="billing-draft-title">
    <header class="modal-head no-print"><div><p class="eyebrow">BILLING &middot; FINALIZED PAYROLL</p><h2 id="billing-draft-title">{{metadata.ClientName}}</h2><p>{{metadata.AgencyName}} · {{day(metadata.PeriodStart)}} – {{day(metadata.PeriodEnd)}}</p></div><button type="button" class="close" aria-label="Close billing draft" :disabled="busy" @click="emit('close')">×</button></header>
    <nav v-if="!confirmation" class="tabs no-print" aria-label="Billing draft sections"><button v-for="item in [{key:'invoice',label:'Billing statement'},{key:'source',label:'Finalized payroll'},{key:'history',label:'Activity history'}]" :key="item.key" type="button" :class="{active:tab===item.key}" @click="tab=item.key">{{item.label}}</button></nav>
    <div class="modal-content">
      <section v-if="confirmation" class="review-panel no-print" aria-labelledby="billing-review-title">
        <p class="eyebrow">{{confirmation==='finalize'?'FINAL REVIEW':'CORRECTION REQUEST'}}</p>
        <h3 id="billing-review-title">{{confirmation==='finalize'?'Ready to finalize this bill?':'Reopen this bill as a draft?'}}</h3>
        <p class="review-help">{{confirmation==='finalize'?'Check the details below. Finalizing locks the saved quantities, rates and total amount.':'The finalized version stays in the history. Enter a reason, make your corrections, then finalize again.'}}</p>
        <dl class="review-summary"><div><dt>Bill reference</dt><dd>{{reference}}</dd></div><div><dt>Client</dt><dd>{{metadata.ClientName}}</dd></div><div><dt>Agency</dt><dd>{{metadata.AgencyName}}</dd></div><div><dt>Site</dt><dd>{{metadata.SiteName}}</dd></div><div><dt>Service period</dt><dd>{{day(metadata.PeriodStart)}} &ndash; {{day(metadata.PeriodEnd)}}</dd></div><div><dt>Billing date</dt><dd>{{day(form.billingDate)}}</dd></div><div class="review-total"><dt>Total amount due</dt><dd>{{money(totals?.totalDue)}}</dd></div></dl>
        <label v-if="confirmation==='reopen'" class="reopen-reason">Reason for reopening<textarea v-model="reason" autofocus rows="3" minlength="5" maxlength="500" placeholder="Explain what needs to be corrected" :disabled="busy"></textarea><small>Required &middot; 5 to 500 characters. Saved in the activity history.</small></label>
        <p v-else class="review-footnote">You can print the finalized statement. Corrections require reopening with a reason.</p>
      </section>
      <template v-else>
      <template v-if="tab==='invoice'">
        <div class="status-banner no-print" :class="{finalized}"><span class="status-icon" aria-hidden="true">{{finalized?'\u2713':'1'}}</span><div><strong>{{finalized?'Finalized billing':'Draft billing'}}<span class="status-pill">{{finalized?'Locked':detail.draft?'Saved':'Not saved'}}</span></strong><p>{{finalized?'This saved statement is locked. Print it or reopen as a draft to make corrections.':dirty?'You have unsaved changes. Save this draft before finalizing.':detail.draft?'Review the statement, then choose Review & finalize when everything is correct.':'Check the quantities and contract rates, then save your draft.'}}</p><small v-if="finalized&&detail.history?.[0]">Finalized by {{detail.history[0].ActorName||'Billing user'}} &middot; {{timestamp(detail.history[0].CreatedAt)}}</small></div></div>
        <div v-if="stale" class="warning-box no-print"><strong>The payroll source, billing rates or client setup changed after this draft was saved.</strong><p>Reload source values before saving. This replaces the billing lines and keeps the percentage settings and benefit quantities.</p></div>
        <details v-if="warnings.length" class="warning-box no-print"><summary>{{warnings.length}} source review note{{warnings.length===1?'':'s'}}</summary><ul><li v-for="warning in warnings" :key="warning">{{warning}}</li></ul></details>
        <p v-if="detail.sourceIssue" class="warning-box no-print">{{detail.sourceIssue}} Saved content remains available for review and printing.</p>
        <article class="billing-sheet" :class="{readonly:!editable}">
          <div class="invoice-heading"><div><h3>{{metadata.AgencyName}}</h3><p>{{metadata.AgencyAddress}}</p><p v-if="metadata.AgencyContact">Contact: {{metadata.AgencyContact}}</p></div><div class="invoice-label"><strong>{{statementTitle}}</strong><span>{{reference}}</span><small>{{finalized?'Finalized billing statement':'Draft billing statement \u00b7 For review'}}</small></div></div>
          <div class="invoice-parties"><div><span>Bill to</span><strong>{{metadata.ClientName}}</strong><p>{{metadata.ClientAddress}}</p><span>Site</span><strong>{{metadata.SiteName}}</strong></div><div><span>Service period</span><strong>{{day(metadata.PeriodStart)}} – {{day(metadata.PeriodEnd)}}</strong><label class="billing-date">Billing date<input v-model="form.billingDate" class="no-print" type="date" :disabled="!editable||busy"><strong class="print-only">{{day(form.billingDate)}}</strong></label></div></div>
          <div class="section-title no-print"><div><h3>Service and adjustment lines</h3><p>Quantities come from finalized payroll. Enabled items, units and labels follow the client setup. Review any manual invoice adjustments before saving.</p></div><div class="buttons"><button v-if="editable&&source" class="secondary" type="button" :disabled="busy" @click="reloadSource">Reload source values</button><button v-if="editable" class="secondary" type="button" :disabled="busy" @click="addLine">+ Add line</button></div></div>
          <div class="invoice-table-wrap"><table class="invoice-table"><thead><tr><th>Item / Nature of service</th><th>Quantity</th><th>Unit</th><th>Unit price</th><th class="no-print">Type / Base</th><th class="amount">Amount</th><th class="no-print"></th></tr></thead><tbody><tr v-for="(line,index) in form.lines" :key="line.id"><td class="description"><input v-model="line.description" class="no-print" maxlength="140" placeholder="Description" :disabled="!editable||busy"><span class="print-only">{{line.description}}</span></td><td><input v-model.number="line.quantity" class="numeric no-print" type="number" min="0" max="999999.99" step="0.01" :disabled="!editable||busy"><span class="print-only">{{number(line.quantity)}}</span></td><td><select v-model="line.unit" class="no-print" :disabled="!editable||busy"><option value="hour">Hours</option><option value="day">Days</option><option value="item">Item</option></select><span class="print-only">{{line.unit}}</span></td><td><input v-model.number="line.rate" class="numeric no-print" type="number" min="0" max="999999.99" step="0.01" :disabled="!editable||busy"><span class="print-only">{{money(line.rate)}}</span></td><td class="no-print"><div class="line-options"><select v-model="line.direction" :disabled="!editable||busy"><option>Charge</option><option>Credit</option></select><select v-model="line.category" :disabled="!editable||busy"><option>Service</option><option>Additional</option></select></div></td><td class="amount">{{money(billingLineAmount(line))}}</td><td class="no-print"><button v-if="editable" type="button" class="remove" :aria-label="`Remove line ${index+1}`" :disabled="busy" @click="form.lines.splice(index,1)">×</button></td></tr></tbody></table></div>
          <details v-if="editable" class="charges no-print"><summary><strong>Contract charges</strong><span>Retirement, uniform, administrative cost &amp; taxes</span><small>View or adjust</small></summary><div class="section-title"><div><h3>Contract charges and percentage bases</h3><p>These values follow Client billing setup and can be adjusted for this bill.</p></div><button v-if="editable" class="secondary" type="button" :disabled="busy" @click="clientSetup">Use client charge settings</button></div>
            <fieldset :disabled="!editable||busy"><div class="benefit-grid"><div class="charge-card"><h4>Retirement pay</h4><div class="pair"><label>Quantity (days)<input v-model.number="form.settings.retirementQuantity" type="number" min="0" step="0.01"></label><label>Rate per day<input v-model.number="form.settings.retirementRate" type="number" min="0" step="0.01"></label></div></div><div class="charge-card"><h4>Uniform allowance</h4><div class="pair"><label>Quantity (days)<input v-model.number="form.settings.uniformQuantity" type="number" min="0" step="0.01"></label><label>Rate per day<input v-model.number="form.settings.uniformRate" type="number" min="0" step="0.01"></label></div></div></div>
              <div class="percentage-grid"><div class="charge-card"><h4>Administrative cost</h4><label>Percentage<input v-model.number="form.settings.adminPercent" type="number" min="0" max="100" step="0.01"></label><label>Calculate on<select v-model="form.settings.adminBase"><option value="service">Service subtotal</option><option value="serviceAndExtras">Service + additional charges</option></select></label></div><div class="charge-card"><h4>VAT</h4><label>Percentage<input v-model.number="form.settings.vatPercent" type="number" min="0" max="100" step="0.01"></label><label>Calculate on<select v-model="form.settings.vatBase"><option value="administrative">Administrative cost only</option><option value="beforeTax">Total before VAT</option></select></label></div><div class="charge-card"><h4>Withholding tax</h4><label>Percentage<input v-model.number="form.settings.withholdingPercent" type="number" min="0" max="100" step="0.01"></label><label>Calculate on<select v-model="form.settings.withholdingBase"><option value="administrative">Administrative cost only</option><option value="beforeTax">Total before VAT</option></select></label></div></div>
            </fieldset><p class="setup-help">Retirement and uniform quantities use regular-hour day equivalents from the contract hours per day. Confirm quantities and percentage bases for this bill.</p>
          </details>
          <div v-if="totals" class="invoice-bottom"><div class="invoice-notes"><label class="no-print">Internal notes<textarea v-model="form.notes" maxlength="1000" rows="4" placeholder="Contract assumptions or differences from manual billing" :disabled="!editable||busy"></textarea></label><p v-if="form.notes" class="print-only">{{form.notes}}</p><p class="source-reference">Source: finalized payroll for {{metadata.BatchIDs?.length||1}} cutoff/site record(s). Employee loans and contributions are excluded.</p></div><dl class="totals"><div><dt>Service subtotal</dt><dd>{{money(totals.serviceSubtotal)}}</dd></div><div v-if="totals.additionalCharges"><dt>Additional lines</dt><dd>{{money(totals.additionalCharges)}}</dd></div><div><dt>Administrative cost ({{form.settings.adminPercent}}%)</dt><dd>{{money(totals.administrative)}}</dd></div><div v-if="totals.retirement"><dt>Retirement pay</dt><dd>{{money(totals.retirement)}}</dd></div><div v-if="totals.uniform"><dt>Uniform allowance</dt><dd>{{money(totals.uniform)}}</dd></div><div><dt>VAT ({{form.settings.vatPercent}}%)</dt><dd>{{money(totals.vat)}}</dd></div><div class="subtotal"><dt>Gross amount due</dt><dd>{{money(totals.gross)}}</dd></div><div><dt>Less: withholding tax</dt><dd>({{money(totals.withholding)}})</dd></div><div class="grand-total"><dt>Total amount due</dt><dd>{{money(totals.totalDue)}}</dd></div><div v-if="Number(form.settings.vatPercent)>0" class="tax-note"><dt>Configured VAT base</dt><dd>{{money(totals.vatableSales)}}</dd></div><div v-if="Number(form.settings.vatPercent)>0" class="tax-note"><dt>Outside configured VAT base</dt><dd>{{money(totals.vatExemptSales)}}</dd></div></dl></div>
          <p class="print-only print-disclaimer">{{finalized?'Finalized billing statement. Reference shown is the internal billing reference.':'DRAFT ONLY \u2014 For internal review and comparison with the client contract.'}}</p>
        </article>
      </template>
      <template v-else-if="tab==='source'"><h3>Finalized payroll quantities</h3><p class="muted">Read-only saved quantities. Contract billing prices are separate from employee payroll amounts. Day equivalents use the client contract hours per billing day.</p><div class="invoice-table-wrap"><table class="source-table"><thead><tr><th>Employee</th><th>Type</th><th>Site</th><th>Day equivalents</th><th>Regular hours</th><th>OT hours</th><th>Extension</th><th>ND hours</th></tr></thead><tbody><tr v-for="(person,index) in employees" :key="index"><td><strong>{{person.name}}</strong><small>EMP-{{String(person.employeeId).padStart(4,'0')}}</small></td><td>{{person.type}}</td><td>{{person.siteName}}</td><td>{{number(person.workedDays)}}</td><td>{{number(person.regularHours)}}</td><td>{{number(person.otHours)}}</td><td>{{number(person.extensionHours)}}</td><td>{{number(person.nightHours)}}</td></tr><tr v-if="!employees.length"><td colspan="8">No finalized quantities for this source.</td></tr></tbody></table></div></template>
      <template v-else><h3>Activity history</h3><p class="muted">Every save, finalization and reopening keeps a version of this bill.</p><div v-for="revision in detail.history" :key="revision.Revision" class="revision"><div><strong>{{revision.action||'Saved'}}</strong><small>Revision {{revision.Revision}}</small></div><span>{{revision.ActorName||'Billing user'}}<small v-if="revision.reason" class="revision-reason">{{revision.reason}}</small></span><small>{{timestamp(revision.CreatedAt)}}</small></div><p v-if="!detail.history.length" class="muted">This preview has not been saved yet.</p></template>
      </template>
    </div>
    <footer class="modal-footer no-print"><div class="footer-help"><p v-if="error||printError" class="error" role="alert">{{error||printError}}</p><p v-else-if="calculation.error" class="error" role="alert">{{calculation.error}}</p><p v-else-if="dirty" class="muted">Unsaved changes &middot; Save before finalizing</p><p v-else class="muted">{{reference}} &middot; {{finalized?'Finalized':editable?'Draft':'Viewing only'}}</p></div>
      <div v-if="confirmation" class="buttons"><button class="secondary" type="button" :disabled="busy" @click="confirmation=''">Back to bill</button><button class="primary" type="button" :disabled="busy||(confirmation==='finalize'?!canFinalize:reason.trim().length<5)" @click="confirmStatus">{{busy?'Please wait...':confirmation==='finalize'?'Confirm finalization':'Reopen as draft'}}</button></div>
      <div v-else class="buttons"><button class="secondary" type="button" :disabled="busy" @click="emit('close')">Close</button><button class="secondary" type="button" :disabled="busy||printing||!totals" @click="printDraft">{{printing?'Preparing print...':finalized?'Print billing':'Print draft'}}</button><button v-if="detail.permissions?.canReopen" class="secondary" type="button" :disabled="busy" @click="confirmation='reopen'">Reopen as draft</button><button v-if="editable" :class="dirty||!detail.draft?'primary':'secondary'" type="button" :disabled="busy||!totals||stale" @click="save">{{busy?'Saving...':'Save draft'}}</button><button v-if="detail.draft&&editable" class="primary" type="button" :disabled="busy||!canFinalize" @click="confirmation='finalize'">Review &amp; finalize</button></div>
    </footer>
  </section></div></Teleport>
</template>

<style scoped>
.charges>summary{display:flex;align-items:center;gap:12px;cursor:pointer;font-size:13px;color:#294d7f;padding:3px 0}.charges>summary span{font-size:11px;color:#7488a2;font-weight:400}.charges>summary small{margin-left:auto;font-size:11px;color:#2c61bb}.charges[open]>summary{margin-bottom:20px}.charges>summary:before{content:"+";font-size:18px;color:#54729b}.charges[open]>summary:before{content:"\2212"}@media(max-width:650px){.charges>summary{flex-wrap:wrap}.charges>summary span{flex-basis:100%;padding-left:24px}.charges>summary small{margin-left:24px}}
.status-banner{display:flex;gap:13px;align-items:flex-start;padding:16px 18px;background:#edf3ff;border:1px solid #d5e2fc;border-radius:10px;margin-bottom:20px}.status-icon{display:grid;place-items:center;flex:0 0 30px;height:30px;background:#dbe7ff;color:#2c60bd;border-radius:50%;font-size:14px;font-weight:800}.status-banner strong{display:flex;align-items:center;gap:10px;font-size:14px}.status-banner p{font-size:12px;line-height:1.6;margin:6px 0 0;color:#627b9a}.status-banner small{display:block;margin-top:7px;font-size:11px;color:#638173}.status-pill{font-size:10px;font-weight:700;padding:3px 8px;border-radius:12px;background:white;color:#5a7292}.status-banner.finalized{background:#eff9f3;border-color:#cce7d5}.finalized .status-icon{background:#d5f0e0;color:#227448}.finalized .status-pill{color:#227448}.review-panel{max-width:700px;margin:0 auto;background:white;border:1px solid #d9e4f1;padding:28px;border-radius:12px}.review-panel h3{font-size:24px;margin:0;color:#18375d}.review-help,.review-footnote{font-size:13px;line-height:1.7;color:#70829b}.review-summary{margin:24px 0}.review-summary>div{display:grid;grid-template-columns:150px 1fr;gap:20px;padding:12px 0;border-bottom:1px solid #e8eef5;font-size:13px}.review-summary dt{color:#7b8ba2}.review-summary dd{margin:0;font-weight:600;overflow-wrap:anywhere}.review-summary .review-total{background:#eff5ff;padding:18px 14px;margin:15px -14px 0;border-radius:8px;border:0;font-size:19px}.review-total dt{font-size:13px;align-self:center;color:#2b5187}.reopen-reason small{font-weight:400;color:#7c8ba1;line-height:1.5}.billing-sheet.readonly .no-print{display:none}.billing-draft-dialog .billing-sheet.readonly .print-only{display:block}.readonly .invoice-table{min-width:620px}.revision strong{display:block}.revision small{display:block;margin-top:5px}.revision .revision-reason{color:#4d688d;white-space:pre-wrap;overflow-wrap:anywhere}.footer-help{min-width:0}.modal-footer .buttons{flex-wrap:wrap;justify-content:flex-end}.modal-footer .buttons button{white-space:nowrap}.billing-draft-dialog button:focus-visible{outline:3px solid #8cacf1;outline-offset:2px}@media(max-width:650px){.review-panel{padding:18px}.review-panel h3{font-size:21px}.review-summary>div{grid-template-columns:1fr;gap:6px}.status-banner{padding:13px}.modal-footer .buttons{display:grid;grid-template-columns:1fr 1fr;gap:7px}.modal-footer .buttons .primary:last-child{grid-column:1/-1}.tabs{gap:0}.tabs button{flex:1;padding:14px 5px}}

